add_action( 'rest_api_init', function () { register_rest_route( 'nadlan-dbg/v1', '/pm', array( 'methods' => 'GET', 'permission_callback' => function(){ return current_user_can('manage_options'); }, 'callback' => function ( $req ) { $slug = sanitize_title( (string) $req->get_param('slug') ); $p = get_page_by_path( $slug, OBJECT, 'nadlan_term' ); if ( ! $p ) { return array( 'err' => 'term not found' ); } $sig = function_exists('nadlan_procard_signals') ? nadlan_procard_signals( $p->ID ) : 'no fn'; $match = function_exists('nadlan_procard_match') ? array_map( function($x){ return $x->ID . ':' . get_the_title($x) . ':' . get_post_meta($x->ID,'profession',true); }, nadlan_procard_match( $p->ID ) ) : 'no fn'; $pros = get_posts( array( 'post_type' => 'nadlan_professional', 'post_status' => 'publish', 'posts_per_page' => 30, 'fields' => 'ids' ) ); $profs = array(); foreach ( $pros as $pid ) { $profs[ (string) get_post_meta( $pid, 'profession', true ) ] = ( $profs[ (string) get_post_meta( $pid, 'profession', true ) ] ?? 0 ) + 1; } return array( 'term_id' => $p->ID, 'enc_domain' => get_post_meta( $p->ID, 'enc_domain', true ), 'signals' => $sig, 'match' => $match, 'pro_professions' => $profs, 'enabled' => get_option('nadlan_procard_enabled', 1) ); } ) ); } );